# Submit using grid from previous run
grid_cols = 22
grid_rows = 27
grid = [[7 for _ in range(grid_cols)] for _ in range(grid_rows)]

grid_line_columns = [0, 5, 10, 15, 20]
marker_rows = [1, 5, 13, 17, 21]
special_rows = [9, 25]

markers = {
    '4': [(1, 0), (1, 5), (5, 0), (5, 5), (13, 10), (13, 15), 
          (17, 0), (17, 5), (17, 10), (17, 15), (21, 0), (21, 5)],
    '6': [(1, 10), (1, 15), (1, 20), (5, 10), (5, 15), (5, 20),
          (9, 0), (9, 5), (13, 0), (13, 5), (21, 15), (21, 20),
          (25, 15), (25, 20)]
}

def predict_v3(row, col):
    if col in grid_line_columns:
        return 7
    if (row, col) in markers['4']:
        return 4
    if (row, col) in markers['6']:
        return 6
    if grid[row][col] == 3:
        return 3
    if row in special_rows:
        return 3
    return 7

output_grid = [[predict_v3(row, col) for col in range(grid_cols)] for row in range(grid_rows)]

